import json, os
# Find all sweep .json files and check for budget
for root, dirs, files in os.walk('.'):
    for fn in files:
        if fn.endswith('.json') and fn.startswith('sweep'):
            path = os.path.join(root, fn)
            try:
                with open(path) as f:
                    d2 = json.load(f2 if 'f2' in dir() else open(path))
                print(fn, ': budget =', d2.get('budget', 'NOT PRESENT'))
            except Exception as e:
                print(fn, ': error', e)
"

